#include <omp.h>
#include <cstddef>
#include <stdexcept>
#include <vector>

double sumOfMinimumElements(std::vector<double> const& x, std::vector<double> const& y) {
    if (x.size() != y.size()) {
        throw std::invalid_argument("sumOfMinimumElements: x and y must have the same length");
    }

    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());
    const double* const xp = x.data();
    const double* const yp = y.data();

    double sum = 0.0;

    #pragma omp parallel for reduction(+:sum) schedule(static)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        const double xi = xp[i];
        const double yi = yp[i];
        sum += (xi < yi) ? xi : yi;
    }

    return sum;
}
